@startuml

class Customer {
  + name
  + address
}

class Account {
  + balance
}

class SavingsAccount extends Account {
  + interestRate
}

class InvestmentAccount extends Account {}

class Stock {
  + ticker
}

class StockOrder {
  + quantity
  + price
  + commission
}

Customer "1" -- "*" Account
Account "1" -- "*" StockOrder
StockOrder "*" -- "1" Stock
InvestmentAccount "1" -- "*" StockOrder

@enduml

